"use client"

import Link from "next/link"
import {
  BookOpenIcon,
  CircleUserRoundIcon,
  LifeBuoyIcon,
  LogOutIcon,
  MonitorIcon,
  MoonIcon,
  NotepadTextIcon,
  SunIcon,
} from "lucide-react"
import { useTheme } from "next-themes"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import type {
  AgentConsoleShell,
  AgentConsoleUser,
} from "@/components/livepeer-ui/contracts"

const themes = [
  { value: "system", label: "System theme", icon: MonitorIcon },
  { value: "light", label: "Light theme", icon: SunIcon },
  { value: "dark", label: "Dark theme", icon: MoonIcon },
]

export function UserMenu({
  content,
  user,
}: {
  content: AgentConsoleShell["userMenu"]
  user: AgentConsoleUser
}) {
  const { theme, setTheme } = useTheme()

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button className="flex w-full items-center gap-3 rounded-sm px-2 py-2 text-left transition-colors outline-none hover:bg-muted focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 aria-expanded:bg-muted" />
        }
      >
        <Avatar className="size-9">
          <AvatarFallback className="bg-foreground text-background">
            P
          </AvatarFallback>
        </Avatar>
        <div className="flex flex-col text-sm leading-tight">
          <span className="font-medium">{user.username}</span>
          <span className="text-muted-foreground">{content.accountLabel}</span>
        </div>
      </DropdownMenuTrigger>
      <DropdownMenuContent side="top" sideOffset={8} className="w-60">
        <div className="flex flex-col gap-2 px-2 pt-1.5 pb-2">
          <span className="truncate text-sm text-muted-foreground">
            {user.email}
          </span>
          <ToggleGroup
            value={[theme ?? "system"]}
            onValueChange={(value) => {
              if (value[0]) setTheme(value[0])
            }}
            className="rounded-lg bg-muted p-0.5"
          >
            {themes.map(({ value, label, icon: Icon }) => (
              <ToggleGroupItem
                key={value}
                value={value}
                size="sm"
                aria-label={label}
                className="flex-1 data-[state=on]:bg-background data-[state=on]:shadow-xs"
              >
                <Icon />
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </div>
        <DropdownMenuSeparator />
        <DropdownMenuItem
          render={<Link href="/mockups/livepeer-agent/account" />}
        >
          <CircleUserRoundIcon />
          {content.manageProfileLabel}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <BookOpenIcon />
          {content.developerDocsLabel}
        </DropdownMenuItem>
        <DropdownMenuItem>
          <NotepadTextIcon />
          {content.termsLabel}
        </DropdownMenuItem>
        <DropdownMenuItem>
          <LifeBuoyIcon />
          {content.helpLabel}
        </DropdownMenuItem>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <LogOutIcon />
          {content.logoutLabel}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export type AgentConsoleLink = { _key?: string; label: string; href: string }

export interface AgentConsoleShell {
  _id: string
  homeAriaLabel: string
  navigation: (AgentConsoleLink & { external: boolean })[]
  userMenu: {
    accountLabel: string
    manageProfileLabel: string
    developerDocsLabel: string
    termsLabel: string
    helpLabel: string
    logoutLabel: string
  }
  auth: {
    dialogLabel: string
    title: string
    description: string
    googleLabel: string
    discordLabel: string
    emailDividerLabel: string
    emailInputLabel: string
    emailPlaceholder: string
    continueLabel: string
  }
}

export interface AgentConsoleUser {
  username: string
  email: string
}

export type VideoBuddyPageName =
  | "home"
  | "characters"
  | "footage"
  | "install"
  | "projects"
  | "protocol"
  | "storyboards"

export type VideoBuddyProtocolIcon = "play" | "blocks" | "cpu"

export interface VideoBuddyPageContent {
  _id: string
  _type: "videoBuddyPageContent"
  page: VideoBuddyPageName
  metadataTitle: string
  heading?: string
  description?: string
  primaryActionLabel?: string
  emptyStateTitle?: string
  supportingText?: string
  protocol?: {
    eyebrow: string
    flowHeading: string
    layers: {
      _key: string
      number: string
      title: string
      description: string
      detail: string
      href: string
      icon: VideoBuddyProtocolIcon
    }[]
    requestHeading: string
    requestSteps: { _key: string; title: string; description: string }[]
    agentPropertyHeading: string
    agentPropertyDescription: string
    paymentPropertyHeading: string
    paymentPropertyDescription: string
    architectureLinkLabel: string
    architectureLinkHref: string
  }
}

export type EditorialLink = { _key?: string; label: string; href: string }
export type LivepeerOrgPageSlug =
  | "home"
  | "livepeer-agent"
  | "playbook-library"
  | "ecosystem"
  | "provide-gpu-compute"

export interface LivepeerOrgSite {
  _id: "livepeerOrgSite"
  homeHref: string
  menuLinks: EditorialLink[]
  footerTagline: string
  footerGroups: { _key: string; title: string; links: EditorialLink[] }[]
  socialLinks: (EditorialLink & {
    service: "discord" | "x" | "github" | "website"
  })[]
  copyright: string
}

export interface EcosystemEditorialApp {
  _key: string
  name: string
  domain: string
  href: string
  description: string
  image: string
  tags: string[]
}

export interface LivepeerOrgPage {
  _id: string
  page: LivepeerOrgPageSlug
  seoTitle: string
  seoDescription?: string
  homeContent?: {
    hero: {
      heading: string
      accent: string
      primaryCta: EditorialLink
      secondaryCta: EditorialLink
    }
    agentFeature: {
      description: string
      installCta: EditorialLink
      libraryCta: EditorialLink
    }
    providerCta: { heading: string; description: string; cta: EditorialLink }
  }
  agentContent?: {
    hero: {
      heading: string
      description: string
      serverUrl: string
      signInCta: EditorialLink
      createAccountCta: EditorialLink
    }
    access: { heading: string; description: string; cta: EditorialLink }
    capabilities: { heading: string; cta: EditorialLink }
    playbooks: { heading: string; description: string; cta: EditorialLink }
  }
  libraryContent?: {
    heading: string
    description: string
    searchPlaceholder: string
    allCategoryLabel: string
    emptyMessage: string
    footerHeading: string
  }
  ecosystemContent?: {
    heading: string
    description: string
    submitLabel: string
    searchPlaceholder: string
    emptyMessage: string
    apps: EcosystemEditorialApp[]
    submission: {
      heading: string
      description: string
      steps: { _key: string; heading: string; description: string }[]
      templatePath: string
      template: string
      closeLabel: string
      githubCta: EditorialLink
    }
  }
  earnContent?: {
    earnings: {
      servicePayoutsLabel: string
      protocolRewardsLabel: string
      periodLabel: string
    }
    hero: { heading: string; description: string; cta: EditorialLink }
    pathsHeading: string
    pathsDescription: string
    paths: {
      _key: string
      heading: string
      fit: string
      description: string
      icon: "cable" | "sparkles" | "server-cog"
      requirements: string[]
      note: string
      cta: EditorialLink
    }[]
    baselineHeading: string
    baselineDescription: string
    baseline: {
      _key: string
      heading: string
      description: string
      icon: "cpu" | "server" | "network" | "dollar"
    }[]
    arbitrum: {
      heading: string
      description: string
      imageAlt: string
      disclaimer: string
      cta: EditorialLink
    }
    stake: { heading: string; description: string; cta: EditorialLink }
  }
}

export interface WaitlistPageContent {
  _id: string
  metadata: { title: string; description: string }
  backgroundHero: { brandAriaLabel: string; agentLabel: string }
  panel: {
    brandAriaLabel: string
    agentLabel: string
    heading: string
    description: string
    joinedToast: string
    referralPrompt: string
  }
  signupForm: {
    label: string
    emailPlaceholder: string
    submitAriaLabel: string
  }
  statusCard: { positionLabel: string; referralsLabel: string }
  referralLink: { copyAriaLabel: string; copiedToast: string }
  leaderboard: {
    heading: string
    personColumnLabel: string
    referralsColumnLabel: string
    currentUserLabel: string
  }
